  }
}
const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
return {
  fetched: all.length,
  uniqueNumbers: nums.size,
  prLike: prLike.length,
  noAssigneesField,
  top5: sorted.slice(0, 5),
};
