  details.push(...res);
}
const toLogins = (x: any): string[] => {
  const list: any[] = x?.assignees ?? (x?.assignee ? [x.assignee] : []);
  return list.map((a: any) => (typeof a === "string" ? a : a?.login)).filter(Boolean);
};
const listMismatch = all.filter((i: any, idx: number) => {
  const d: any = details.find((x: any) => x?.number === i.number);
  return d && JSON.stringify(toLogins(i).sort()) !== JSON.stringify(toLogins(d).sort());
}).length;
const counts: Record<string, number> = {};
for (const d of details) {
  for (const login of toLogins(d)) counts[login] = (counts[login] ?? 0) + 1;
}
const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
return {
  listed: all.length,
  detailed: details.length,
  listMismatch,
  sampleDetailKeys: details[0] ? Object.keys(details[0]) : null,
  top5: sorted.slice(0, 5),
};
